SELECT cron.schedule('b2b-monthly-tier-assessment','35 18 * * *',$job$ DO $body$ DECLARE v uuid; b record; BEGIN SELECT id INTO v FROM public.b2b_pricing_versions WHERE status='published' AND enabled AND effective_from<=now() AND (effective_until IS NULL OR effective_until>now()) ORDER BY effective_from DESC LIMIT 1; IF v IS NOT NULL THEN FOR b IN SELECT id FROM public.business_accounts WHERE is_active AND status='approved' LOOP PERFORM public.b2b_resolve_month(b.id,v); END LOOP; END IF; END $body$; $job$);